defmodule FeatureType do
  @valid_enum_members [
    :Feature,
  ]

  def valid_atom?(value), do: value in @valid_enum_members

  def valid_atom_string?(value) do
    try do
        atom = String.to_existing_atom(value)
        atom in @valid_enum_members
    rescue
        ArgumentError -> false
    end
  end

  def encode(value) do
    if valid_atom?(value) do
        Atom.to_string(value)
    else
        {:error, "Unexpected value when encoding atom: #{inspect(value)}"}
    end
  end

  def decode(value) do
    if valid_atom_string?(value) do
        String.to_existing_atom(value)
    else
        {:error, "Unexpected value when decoding atom: #{inspect(value)}"}
    end
  end

  def from_json(json) do
    json
    |> Jason.decode!()
    |> decode()
  end

  def to_json(data) do
    data
    |> encode()
    |> Jason.encode!()
  end
end

defmodule Feature do
  @enforce_keys [:geometry, :geometry_name, :id, :properties, :type]
  defstruct [:geometry, :geometry_name, :id, :properties, :type]

  @type t :: %__MODULE__{
          geometry: Geometry.t(),
          geometry_name: GeometryName.t(),
          id: String.t(),
          properties: FeatureProperties.t(),
          type: FeatureType.t()
        }

  def decode_id(value) when is_binary(value), do: value
  def decode_id(_), do: {:error, "Unexpected type when decoding Feature.id"}

  def encode_id(value) when is_binary(value), do: value
  def encode_id(_), do: {:error, "Unexpected type when encoding Feature.id"}

  def from_map(m) do
    %Feature{
      geometry: Geometry.from_map(m["geometry"]),
      geometry_name: GeometryName.decode(m["geometry_name"]),
      id: decode_id(m["id"]),
      properties: FeatureProperties.from_map(m["properties"]),
      type: FeatureType.decode(m["type"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "geometry" => Geometry.to_map(struct.geometry),
      "geometry_name" => GeometryName.encode(struct.geometry_name),
      "id" => struct.id,
      "properties" => FeatureProperties.to_map(struct.properties),
      "type" => FeatureType.encode(struct.type),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

defmodule TopLevel do
  @enforce_keys [:crs, :features, :total_features, :type]
  defstruct [:crs, :features, :total_features, :type]

  @type t :: %__MODULE__{
          crs: CRS.t(),
          features: [Feature.t()],
          total_features: integer(),
          type: String.t()
        }

  def decode_features(value) when is_list(value), do: value
  def decode_features(_), do: {:error, "Unexpected type when decoding TopLevel.features"}

  def encode_features(value) when is_list(value), do: value
  def encode_features(_), do: {:error, "Unexpected type when encoding TopLevel.features"}

  def decode_total_features(value) when is_integer(value), do: value
  def decode_total_features(_), do: {:error, "Unexpected type when decoding TopLevel.total_features"}

  def encode_total_features(value) when is_integer(value), do: value
  def encode_total_features(_), do: {:error, "Unexpected type when encoding TopLevel.total_features"}

  def decode_type(value) when is_binary(value), do: value
  def decode_type(_), do: {:error, "Unexpected type when decoding TopLevel.type"}

  def encode_type(value) when is_binary(value), do: value
  def encode_type(_), do: {:error, "Unexpected type when encoding TopLevel.type"}

  def from_map(m) do
    %TopLevel{
      crs: CRS.from_map(m["crs"]),
      features: Enum.map(m["features"], &Feature.from_map/1),
      total_features: decode_total_features(m["totalFeatures"]),
      type: decode_type(m["type"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "crs" => CRS.to_map(struct.crs),
      "features" => struct.features && Enum.map(struct.features, &Feature.to_map/1),
      "totalFeatures" => struct.total_features,
      "type" => struct.type,
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end
